    hawaii_emails = search_emails(query="Hawaii", sender=None)
else:
    hawaii_emails = []

# Extract packing list items from events or emails
packing_list_items = []

# Check calendar events first
for event in hawaii_events:
    # Extract items from event description or title
    content = event.description + " " + event.title
    lines = content.splitlines()
    for line in lines:
        line = line.strip()
        if line and (line.startswith("-") or line.startswith("*") or line[0].isdigit() or (len(line) < 50 and len(line) > 2)):
            packing_list_items.append(line)

# If no items from events, check emails
if not packing_list_items:
    for email in hawaii_emails:
        body = email.body
        lines = body.splitlines()
        for line in lines:
            line = line.strip()
            if line and not line.startswith("Subject:") and not line.startswith("From:"):
                if line.startswith("-") or line.startswith("*") or line[0].isdigit() or (len(line) < 50 and len(line) > 2):
                    packing_list_items.append(line)

# If still no items, try searching for "trip" or "vacation" in emails
if not packing_list_items:
